// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate for precise slap, squash, and peel physics

const { fontFamily: oswaldFamily } = loadOswald();
const { fontFamily: interFamily } = loadInter();



export type ProductStampProps = Record<string, any>;

const ProductStamp: React.FC<ProductStampProps> = ({
  backgroundColor = "#1c2e4a",
  transparentBackground = false,
  durationInSeconds = 4,
  productNameLine1 = "GREY",
  productNameLine2 = "LONG JOHNS",
  secondaryText = "SKULL CAP",
  badgeText = "SUMMER 2",
  tagColor = "#f4eadc",
  borderColor = "#f0b5ce",
  innerBorderColor = "#7cb6d8",
  textColor = "#132644",
  badgeColor = "#7cb6d8",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const durationInFrames = durationInSeconds * fps;

  // --- Animation Physics ---

  // 1. Entrance Drop
  const entranceDuration = 16;
  const dropY = interpolate(frame, [0, entranceDuration], [-1500, 0], {
    easing: Easing.in(Easing.exp),
    extrapolateRight: "clamp",
  });
  const dropRotation = interpolate(frame, [0, entranceDuration], [-15, 0], {
    easing: Easing.out(Easing.quad),
    extrapolateRight: "clamp",
  });

  // 2. Impact Squash & Overshoot
  const squashStart = entranceDuration;
  const squashScaleY = interpolate(
    frame,
    [squashStart - 1, squashStart, squashStart + 4, squashStart + 10],
    [1, 0.8, 1.05, 1],
    {
      easing: Easing.out(Easing.quad),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const squashScaleX = interpolate(
    frame,
    [squashStart - 1, squashStart, squashStart + 4, squashStart + 10],
    [1, 1.06, 0.98, 1],
    {
      easing: Easing.out(Easing.quad),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Dynamic drop shadow tightening on impact
  const shadowOffset = interpolate(frame, [0, squashStart], [80, 15], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const shadowBlur = interpolate(frame, [0, squashStart], [50, 20], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const shadowOpacity = interpolate(frame, [0, squashStart], [0.1, 0.3], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // 3. Exit Peel Away
  const exitDuration = 25;
  const exitStart = durationInFrames - exitDuration;
  const exitProgress = interpolate(frame, [exitStart, durationInFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.in(Easing.quad),
  });

  const exitY = interpolate(exitProgress, [0, 1], [0, 1500]);
  const exitX = interpolate(exitProgress, [0, 1], [0, 400]);
  const exitRotX = interpolate(exitProgress, [0, 1], [0, 65]);
  const exitRotZ = interpolate(exitProgress, [0, 1], [0, 25]);

  // Combine Transforms
  const currentY = dropY + exitY;
  const currentX = exitX;
  const currentRotZ = dropRotation + exitRotZ;

  // --- SVG Tag Geometry ---
  const tagW = 800;
  const tagH = 880;
  const topY = 180; // The Y coordinate where the straight top edge begins
  const rx = 60; // Corner radius
  const tabRadius = 95;
  
  // Hardcoded intersection points calculated for a smooth tab join
  // Given tab center (400, 130) and radius 95, intersecting line y=180
  const ix1 = 318;
  const ix2 = 482;

  const tagOutlinePath = `
    M ${rx} ${topY}
    L ${ix1} ${topY}
    A ${tabRadius} ${tabRadius} 0 1 1 ${ix2} ${topY}
    L ${tagW - rx} ${topY}
    A ${rx} ${rx} 0 0 1 ${tagW} ${topY + rx}
    L ${tagW} ${tagH - rx}
    A ${rx} ${rx} 0 0 1 ${tagW - rx} ${tagH}
    L ${rx} ${tagH}
    A ${rx} ${rx} 0 0 1 0 ${tagH - rx}
    L 0 ${topY + rx}
    A ${rx} ${rx} 0 0 1 ${rx} ${topY}
    Z
  `;

  // Chrome Star Geometry
  const starPath = `M 400 230 Q 400 260 280 260 Q 400 260 400 290 Q 400 260 520 260 Q 400 260 400 230 Z`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          perspective: 1200, // For the 3D peel effect
          transition: "none",
        }}
      >
        {/* Main Tag Wrapper */}
        <div
          style={{
            width: tagW,
            height: tagH,
            transformOrigin: "center center",
            transform: `
              scale(${s}) 
              translate3d(${currentX}px, ${currentY}px, 0)
              scaleX(${squashScaleX}) 
              scaleY(${squashScaleY}) 
              rotateZ(${currentRotZ}deg)
              rotateX(${exitRotX}deg)
            `,
            filter: `drop-shadow(0px ${shadowOffset}px ${shadowBlur}px rgba(0,0,0,${shadowOpacity}))`,
            transition: "none",
            position: "relative",
          }}
        >
          {/* Base SVG Shape */}
          <svg
            width="100%"
            height="100%"
            viewBox={`0 0 ${tagW} ${tagH}`}
            style={{ position: "absolute", top: 0, left: 0, transition: "none" }}
          >
            <defs>
              <mask id="tag-hole">
                <rect width="100%" height="100%" fill="white" />
                <circle cx="400" cy="115" r="28" fill="black" />
              </mask>
              <linearGradient id="chrome" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#ffffff" />
                <stop offset="30%" stopColor="#d1d1d1" />
                <stop offset="50%" stopColor="#8a8a8a" />
                <stop offset="70%" stopColor="#e0e0e0" />
                <stop offset="100%" stopColor="#4a4a4a" />
              </linearGradient>
              <linearGradient id="gloss" x1="0%" y1="0%" x2="0%" y2="100%">
                <stop offset="0%" stopColor="#ffffff" stopOpacity="0.4" />
                <stop offset="30%" stopColor="#ffffff" stopOpacity="0.0" />
                <stop offset="100%" stopColor="#000000" stopOpacity="0.05" />
              </linearGradient>
              <filter id="star-shadow" x="-20%" y="-20%" width="140%" height="140%">
                <feDropShadow dx="0" dy="8" stdDeviation="6" floodOpacity="0.5" />
              </filter>
            </defs>

            {/* Base Fill & Thick Pink Border */}
            <path
              d={tagOutlinePath}
              fill={tagColor}
              stroke={borderColor}
              strokeWidth="28"
              mask="url(#tag-hole)"
              style={{ transition: "none" }}
            />

            {/* Gloss Overlay for Plastic/Sticker Feel */}
            <path
              d={tagOutlinePath}
              fill="url(#gloss)"
              mask="url(#tag-hole)"
              style={{ transition: "none" }}
            />

            {/* Inner Thin Blue Line */}
            <rect
              x="50"
              y="225"
              width={tagW - 100}
              height={tagH - 225 - 50}
              rx="40"
              fill="none"
              stroke={innerBorderColor}
              strokeWidth="5"
              style={{ transition: "none" }}
            />

            {/* Pink Divider Line */}
            <line
              x1="180"
              y1="590"
              x2="620"
              y2="590"
              stroke={borderColor}
              strokeWidth="4"
              strokeLinecap="round"
              style={{ transition: "none" }}
            />

            {/* Chrome Star Accent */}
            <path
              d={starPath}
              fill="url(#chrome)"
              filter="url(#star-shadow)"
              style={{ transition: "none" }}
            />
          </svg>

          {/* HTML Overlay for Typography */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              transition: "none",
            }}
          >
            {/* Main Product Name */}
            <div
              style={{
                marginTop: "330px",
                fontFamily: oswaldFamily,
                fontSize: "125px",
                fontWeight: 600,
                color: textColor,
                lineHeight: 0.95,
                textAlign: "center",
                textTransform: "uppercase",
                letterSpacing: "4px",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                transition: "none",
              }}
            >
              <span>{productNameLine1}</span>
              <span>{productNameLine2}</span>
            </div>

            {/* Secondary Text */}
            <div
              style={{
                marginTop: "70px",
                fontFamily: interFamily,
                fontSize: "44px",
                fontWeight: 700,
                color: textColor,
                textTransform: "uppercase",
                letterSpacing: "8px",
                transition: "none",
              }}
            >
              {secondaryText}
            </div>

            {/* Pill Badge */}
            <div
              style={{
                marginTop: "45px",
                backgroundColor: badgeColor,
                padding: "12px 50px",
                borderRadius: "50px",
                fontFamily: interFamily,
                fontSize: "32px",
                fontWeight: 800,
                color: textColor,
                textTransform: "uppercase",
                letterSpacing: "8px",
                boxShadow: "inset 0px 4px 6px rgba(255,255,255,0.4), 0px 6px 12px rgba(0,0,0,0.15)",
                border: `1px solid rgba(0,0,0,0.05)`,
                transition: "none",
              }}
            >
              {badgeText}
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ProductStamp;